module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg [23:0] a_mantissa, b_mantissa, z_mantissa;
reg [9:0] a_exponent, b_exponent, z_exponent;
reg a_sign, b_sign, z_sign;
reg [49:0] product;
reg guard_bit, round_bit, sticky;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        counter <= 3'b000;
        a_mantissa <= 24'b0;
        b_mantissa <= 24'b0;
        z_mantissa <= 24'b0;
        a_exponent <= 10'b0;
        b_exponent <= 10'b0;
        z_exponent <= 10'b0;
        a_sign <= 1'b0;
        b_sign <= 1'b0;
        z_sign <= 1'b0;
        product <= 50'b0;
        guard_bit <= 1'b0;
        round_bit <= 1'b0;
        sticky <= 1'b0;
        z <= 32'b0;
    end else begin
        case (counter)
            3'b000: begin 
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= {a[22:0], 1'b1}; 
                b_mantissa <= {b[22:0], 1'b1}; 
            end
            3'b001: begin 

            end
            3'b010: begin 
                product <= $signed(a_mantissa) * $signed(b_mantissa);
                z_exponent <= a_exponent + b_exponent - 127; 
                z_sign <= a_sign ^ b_sign; 
            end
            3'b011: begin 

            end
            3'b100: begin 

                z <= {z_sign, z_exponent, z_mantissa};
            end
            default: counter <= 3'b000;
        endcase
        counter <= counter + 1;
    end
end

endmodule
